window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ad03b0a82e75c4d6"]={"versions": [{"id": "FIG-ad03b0a82e75c4d6", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware- und Software-Bereitstellungsdiagramm (Deployment- und Testsetup-Architektur) für den Systemtest des AUTOSAR Adaptive Platform Communication Management (CM). Dargestellt ist eine verteilte Testumgebung bestehend aus zwei physischen Adaptive-ECU-Zielen und einem Teststeuerungs-Host (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei vertikale Rechenknoten:</p>\n<ul class=\"fig-list\">\n<li><strong>ECU1</strong>: Basiert auf der Zielhardware <code>Intel MinnowBoard</code> mit <code>Linux with Real-time Patches</code>. Der Software-Stack umfasst <code>POSIX libs (libc, ...)</code>, die Kommunikations-Middleware <code>vSomeIP</code>, die Zwischenschicht <code>ARA</code> (AUTOSAR Runtime for Adaptive Applications) sowie die Anwendung <code>Video Data</code>.</li>\n<li><strong>ECU2</strong>: Basiert auf der Zielhardware <code>Renesas R-CAR H3 ULCB</code> mit <code>Linux with Real-time Patches</code>. Der Software-Stack enthält identisch aufgebaute Schichten aus <code>POSIX libs (libc, ...)</code>, <code>vSomeIP</code> und <code>ARA</code>, auf denen <code>System Test Applications</code> ausgeführt werden.</li>\n<li><strong>Jenkins</strong>: Basiert auf Standard-Hardware <code>PC</code> mit <code>Linux with Real-time Patches</code>, auf der das <code>Jenkins</code>-System und die Testapplikation <code>CM Tester</code> laufen.</li>\n<li><strong>Verbindungen & Schnittstellen</strong>: Gestrichelte Pfeile symbolisieren Kommunikationsflüsse auf Netzwerk- und Anwendungsebene zwischen den drei Knoten, jeweils von den Applikationen durch die Middleware-Schichten über das physische Netzwerk.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Testinfrastruktur zur Abbildung von Ende-zu-Ende-Kommunikationsabläufen:</p>\n<ul class=\"fig-list\">\n<li><code>Video Data</code> auf ECU1 und <code>System Test Applications</code> auf ECU2 kommunizieren untereinander über Ethernet mittels SOME/IP (<code>vSomeIP</code>) und <code>ARA</code> (Kommunikationspfad über die jeweiligen Schnittstellen).</li>\n<li>Der <code>CM Tester</code> auf dem Jenkins-PC steuert die Testszenarien bzw. empfängt Testdaten und interagiert parallel über das Netzwerk mit den Applikationen auf ECU1 und ECU2.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informatives Architektur- und Testaufbaudiagramm für Adaptive-Platform-Systemtests (TR_AdaptivePlatformSystemTests). Dient Entwicklern und Integratoren als Referenzaufbau zur Validierung von SOME/IP-basierter Dienstkommunikation über <code>ara::com</code> auf heterogener Hardware (x86_64 und ARM64). Enthält keine formalen normativen Schnittstellendefinitionen, spezifiziert jedoch die zugrunde liegende Linux-Echtzeit- und Middleware-Konfiguration.</p>"}, {"id": "FIG-92cfa9af6ced8d74", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware- und Software-Bereitstellungsdiagramm (Deployment- und Testsetup-Architektur) für den Systemtest des AUTOSAR Adaptive Platform Communication Management (CM). Dargestellt ist eine verteilte Testumgebung bestehend aus zwei physischen Adaptive-ECU-Zielen und einem Teststeuerungs-Host (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei vertikale Rechenknoten:</p>\n<ul class=\"fig-list\">\n<li><strong>ECU1</strong>: Basiert auf der Zielhardware <code>Intel MinnowBoard</code> mit <code>Linux with Real-time Patches</code>. Der Software-Stack umfasst <code>POSIX libs (libc, ...)</code>, die Kommunikations-Middleware <code>vSomeIP</code>, die Zwischenschicht <code>ARA</code> (AUTOSAR Runtime for Adaptive Applications) sowie die Anwendung <code>Video Data</code>.</li>\n<li><strong>ECU2</strong>: Basiert auf der Zielhardware <code>Renesas R-CAR H3 ULCB</code> mit <code>Linux with Real-time Patches</code>. Der Software-Stack enthält identisch aufgebaute Schichten aus <code>POSIX libs (libc, ...)</code>, <code>vSomeIP</code> und <code>ARA</code>, auf denen <code>System Test Applications</code> ausgeführt werden.</li>\n<li><strong>Jenkins</strong>: Basiert auf Standard-Hardware <code>PC</code> mit <code>Linux with Real-time Patches</code>, auf der das <code>Jenkins</code>-System und die Testapplikation <code>CM Tester</code> laufen.</li>\n<li><strong>Verbindungen & Schnittstellen</strong>: Gestrichelte Pfeile symbolisieren Kommunikationsflüsse auf Netzwerk- und Anwendungsebene zwischen den drei Knoten, jeweils von den Applikationen durch die Middleware-Schichten über das physische Netzwerk.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Testinfrastruktur zur Abbildung von Ende-zu-Ende-Kommunikationsabläufen:</p>\n<ul class=\"fig-list\">\n<li><code>Video Data</code> auf ECU1 und <code>System Test Applications</code> auf ECU2 kommunizieren untereinander über Ethernet mittels SOME/IP (<code>vSomeIP</code>) und <code>ARA</code> (Kommunikationspfad über die jeweiligen Schnittstellen).</li>\n<li>Der <code>CM Tester</code> auf dem Jenkins-PC steuert die Testszenarien bzw. empfängt Testdaten und interagiert parallel über das Netzwerk mit den Applikationen auf ECU1 und ECU2.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informatives Architektur- und Testaufbaudiagramm für Adaptive-Platform-Systemtests (TR_AdaptivePlatformSystemTests). Dient Entwicklern und Integratoren als Referenzaufbau zur Validierung von SOME/IP-basierter Dienstkommunikation über <code>ara::com</code> auf heterogener Hardware (x86_64 und ARM64). Enthält keine formalen normativen Schnittstellendefinitionen, spezifiziert jedoch die zugrunde liegende Linux-Echtzeit- und Middleware-Konfiguration.</p>"}], "trans": [{"from": "FIG-ad03b0a82e75c4d6", "to": "FIG-92cfa9af6ced8d74", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammoberkante: Eine Zeile Textanschnitt aus dem vorausgehenden Fließtext („Diagnostics functional cluster in form of diagnostic messages.“) wurde oben links in den Bildbereich mitkopiert.</li>\n</ul>"}]};
